"""Minimal demo service for the metricsd connection example.

Echoes a functional response when the example context (X-Demo-Token header)
matches the public protocol sample. The token is not an authorization
credential; it selects the demonstration echo path.
"""

import json
from http.server import BaseHTTPRequestHandler, HTTPServer

EXAMPLE_TOKEN = "PUBLIC_SAMPLE_NO_AUTHORITY"


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        token = self.headers.get("X-Demo-Token", "")
        if token == EXAMPLE_TOKEN:
            body = json.dumps(
                {
                    "service": "metricsd",
                    "status": "ok",
                    "context": "example",
                    "message": "functional demonstration response",
                }
            ).encode()
            self.send_response(200)
        else:
            body = json.dumps(
                {"service": "metricsd", "status": "no-context"}
            ).encode()
            self.send_response(400)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, *args):
        pass


def main(host="127.0.0.1", port=8061):
    HTTPServer((host, port), Handler).serve_forever()


if __name__ == "__main__":
    main()

